# ---- producer.py ----
from confluent_kafka import Producer
import json

producer = Producer({
    "bootstrap.servers": "localhost:9092",
    "acks": "all",              # wait for all in-sync replicas -> durable
    "enable.idempotence": True, # avoid duplicate records on retries
})

def delivered(err, msg):
    if err:
        print(f"delivery failed: {err}")
    else:
        print(f"delivered to {msg.topic()}[{msg.partition()}]@{msg.offset()}")

orders = [
    {"order_id": 1, "customer": "alice", "amount": 42},
    {"order_id": 2, "customer": "bob", "amount": 17},
]
for o in orders:
    producer.produce(
        "orders",
        key=o["customer"],          # key by customer -> ordering per customer
        value=json.dumps(o),
        callback=delivered,
    )
producer.flush()  # block until all records are delivered

# ---- consumer.py ----
from confluent_kafka import Consumer
import json

consumer = Consumer({
    "bootstrap.servers": "localhost:9092",
    "group.id": "order-processor",     # consumer group name
    "auto.offset.reset": "earliest",   # new group reads from the start
})
consumer.subscribe(["orders"])

try:
    while True:
        msg = consumer.poll(1.0)
        if msg is None:
            continue
        if msg.error():
            print(f"error: {msg.error()}")
            continue
        order = json.loads(msg.value())
        print(f"processing order {order['order_id']} for {order['customer']} (${order['amount']})")
finally:
    consumer.close()
